import{describe,it,expect}from"vitest";import{INDIAN_SUPERLATIVES_DATA,filterSuperlatives,getSuperlativeBadgeClass,getComparisonData}from"../../frontend/indian-superlatives-explorer/script.js";describe("Interactive Indian Superlatives Explorer",()=>{it("should contain a comprehensive dataset of Indian Superlatives",()=>{expect(Array.isArray(INDIAN_SUPERLATIVES_DATA)).toBe(!0),expect(INDIAN_SUPERLATIVES_DATA.length).toBeGreaterThanOrEqual(20),INDIAN_SUPERLATIVES_DATA.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("name"),expect(e).toHaveProperty("type"),expect(e).toHaveProperty("typeLabel"),expect(e).toHaveProperty("category"),expect(e).toHaveProperty("value"),expect(e).toHaveProperty("numericValue"),expect(e).toHaveProperty("unit"),expect(e).toHaveProperty("state"),expect(e).toHaveProperty("location"),expect(e).toHaveProperty("mapCoords"),expect(e.mapCoords).toHaveProperty("x"),expect(e.mapCoords).toHaveProperty("y"),expect(e).toHaveProperty("description"),expect(e).toHaveProperty("keyStats"),expect(Array.isArray(e.keyStats)).toBe(!0),expect(e.keyStats.length).toBeGreaterThan(0),expect(e).toHaveProperty("facts"),expect(Array.isArray(e.facts)).toBe(!0),expect(e.facts.length).toBeGreaterThan(0),expect(e).toHaveProperty("image")})}),it("should filter superlatives by search keyword",()=>{const e=filterSuperlatives(INDIAN_SUPERLATIVES_DATA,"Ganga");expect(e.length).toBeGreaterThanOrEqual(1),expect(e[0].name).toBe("Ganga River");const t=filterSuperlatives(INDIAN_SUPERLATIVES_DATA,"Dam");expect(t.length).toBeGreaterThanOrEqual(2);const r=filterSuperlatives(INDIAN_SUPERLATIVES_DATA,"Stadium");expect(r.length).toBe(1),expect(r[0].name).toBe("Narendra Modi Stadium")}),it("should filter superlatives by superlative type (largest, highest, longest, oldest)",()=>{const e=filterSuperlatives(INDIAN_SUPERLATIVES_DATA,"","largest");expect(e.length).toBeGreaterThanOrEqual(5),e.forEach(e=>expect(e.type).toBe("largest"));const t=filterSuperlatives(INDIAN_SUPERLATIVES_DATA,"","highest");expect(t.length).toBeGreaterThanOrEqual(5),t.forEach(e=>expect(e.type).toBe("highest"));const r=filterSuperlatives(INDIAN_SUPERLATIVES_DATA,"","longest");expect(r.length).toBeGreaterThanOrEqual(4),r.forEach(e=>expect(e.type).toBe("longest"));const a=filterSuperlatives(INDIAN_SUPERLATIVES_DATA,"","oldest");expect(a.length).toBeGreaterThanOrEqual(5),a.forEach(e=>expect(e.type).toBe("oldest"))}),it("should filter superlatives by category",()=>{const e=filterSuperlatives(INDIAN_SUPERLATIVES_DATA,"","all","Geography & Nature");expect(e.length).toBeGreaterThanOrEqual(5),e.forEach(e=>expect(e.category).toBe("Geography & Nature"));const t=filterSuperlatives(INDIAN_SUPERLATIVES_DATA,"","all","Infrastructure & Engineering");expect(t.length).toBeGreaterThanOrEqual(4),t.forEach(e=>expect(e.category).toBe("Infrastructure & Engineering"))}),it("should return correct badge CSS classes for superlative types",()=>{expect(getSuperlativeBadgeClass("largest")).toBe("badge-largest"),expect(getSuperlativeBadgeClass("highest")).toBe("badge-highest"),expect(getSuperlativeBadgeClass("longest")).toBe("badge-longest"),expect(getSuperlativeBadgeClass("oldest")).toBe("badge-oldest"),expect(getSuperlativeBadgeClass("unknown")).toBe("badge-default")}),it("should generate sorted comparison data for infographics",()=>{const e=getComparisonData(INDIAN_SUPERLATIVES_DATA,"highest");expect(e.length).toBeGreaterThan(0);for(let t=0;t<e.length-1;t++)expect(e[t].numericValue).toBeGreaterThanOrEqual(e[t+1].numericValue)})});